"""Literature-grounded biology and a transparent post-hoc example."""
from pathlib import Path
import json,shutil,hashlib
import numpy as np,pandas as pd
R=Path(__file__).resolve().parent;B=R.parent;W=B/'conference_manuscript_20261027'

def augment(paper,bib,keys,text,heading,table,figure,page):
 completion=json.loads((R/'case_completion.json').read_text());assert completion['state']=='complete'
 for n in ['protocol_case_study.json','CASE_LOCK.json','case_completion.json','gene_coverage.csv','all_observed_member_responses.csv','all_observed_modules.csv','all_case_model_seed_scores.csv','case_model_summary.csv']:
  shutil.copy2(R/n,W/('BCL9_'+n))
 additions={
 'bcl9_immune':{'doi':'10.1038/s41401-026-01845-2','title':'Targeting BCL9/BCL9L enhances CD4+ T cell-mediated Th1 antitumor immunity through activation of STAT1/STAT4 signaling','authors':['Yuan-yuan Zhu','An-qi Li','Fan Yang','Yu-xuan Dong','Ya-si Huang','Xiang-jing Meng','Dai-zhou Zhang','Ye Li','Yan-fang Xian','Di Zhu','Mei Feng'],'venue':['Acta Pharmacologica Sinica'],'published':{'date-parts':[[2026,6,29]]},'type':'journal-article'},
 'bcl9_glioma':{'doi':'10.1021/acsptsci.6c00284','title':'Pharmacological Study of Novel Small-Molecule Inhibitors Targeting B-Cell Lymphoma 9/beta-Catenin in the Treatment of Glioma','authors':['Huiyu Li','Xiaoxuan Lu','Yangbo He','Gang Chen','Yangqiang Chen','Ruihua Sun','Duanjun Guo','Xiangling Tang','Jiewen Zhang','Yujun Zhao','Andrew Zhu','Yan-Fang Xian','Di Zhu','Mei Feng'],'venue':['ACS Pharmacology & Translational Science'],'published':{'date-parts':[[2026,10,17]]},'type':'journal-article'}}
 bib.update(additions);keys.extend(additions)
 refs=next(pg for pg in paper if pg[0].get('text')=='References')
 refs.extend([text('[11] Yuan-yuan Zhu, An-qi Li, Fan Yang, et al. Targeting BCL9/BCL9L enhances CD4+ T cell-mediated Th1 antitumor immunity through activation of STAT1/STAT4 signaling. Acta Pharmacologica Sinica 47, 3024-3041 (2026). DOI: 10.1038/s41401-026-01845-2.'),text('[12] Huiyu Li, Xiaoxuan Lu, Yangbo He, et al. Pharmacological Study of Novel Small-Molecule Inhibitors Targeting B-Cell Lymphoma 9/beta-Catenin in the Treatment of Glioma. ACS Pharmacology & Translational Science, published online 17 October 2026. DOI: 10.1021/acsptsci.6c00284.')])
 paper[0][6]=text('Primary-T perturbation prediction has a concrete pharmacological motivation. BCL9/BCL9L inhibition has been linked to PIAS regulation and STAT1/STAT4-dependent Th1 antitumor function in murine experiments [11]. Separately, ZD37-28R disruption of BCL9/beta-catenin affects MYC-SREBP1-associated lipid programs in glioma models [12]. These cell-specific effects motivate context-aware prediction, while illustrating its required evidence boundaries: transcripts, phosphoprotein activity, cell killing and organ efficacy are distinct endpoints. We test whether the existing FVcell response operator supports such interpretation before extrapolating it to therapeutic simulation.')
 paper[0][4]['text']+=' A literature-selected BCL9/BCL9L illustration further separates transcript proxies from phosphoprotein, drug and organ endpoints.'
 paper[3].extend([heading('4.3  Literature-selected mechanism illustration'),text('Following the main analyses, we fixed a post-hoc BCL9/BCL9L case protocol before inspecting its selected response values. All 24 source target-donor-culture aggregates are retained. The illustration uses PIAS1/2/4 and a six-gene Th1/cytotoxic RNA proxy, with equal member weights and no significance filtering. Frozen fold 0 weights are evaluated on all six corresponding held-donor aggregates and all three source seeds. The target choice is literature-driven and the case is not independent confirmation (Appendix D).')])
 paper[8].extend([heading('7.4  BCL9/BCL9L mechanism illustration'),text('Both BCL9 and BCL9L are present in the source study. In the six fold-0 held-donor aggregates, the observed PIAS transcript-module mean is +0.0410, whereas the Th1/cytotoxic RNA-proxy mean is -0.3683. These do not consistently reproduce the transported hypotheses of PIAS reduction and effector enhancement from the mouse double-perturbation study [11]. All targets, cultures, donors, module members and model seeds remain visible. Single-gene CRISPRi, murine dual deletion and pharmacological inhibition are distinct interventions. This case strengthens the biological question and the audit of assay boundaries; it does not validate the published mechanism in humans or rescue the unfavorable external benchmark results.')])
 paper[9][0]=heading('7.5  Cell-line measurement and negative controls')
 paper[9][7]=text('The intended application is a staged link from target intervention to cell response, measured function and, eventually, tissue behavior. Target-to-organ simulation is a future application; multi-organ, corpus-scale and task-coverage capabilities are not established by this benchmark. FVcell currently predicts terminal aggregate RNA responses. STAT phosphorylation requires protein assays, tumor killing requires functional measurements, and drug-to-organ transfer requires exposure and matched tissue data. The glioma work explicitly lacks pharmacokinetic and brain/tumor exposure measurements [12]. We therefore do not infer blood-brain barrier transport, organ safety, temporal trafficking or clinical benefit.')
 summary=pd.read_csv(R/'case_model_summary.csv');obs=pd.read_csv(R/'all_observed_modules.csv')
 import matplotlib.pyplot as plt
 fig,axs=plt.subplots(1,2,figsize=(6.5,2.35));cultures=['Rest','Stim8hr','Stim48hr'];colors={'BCL9':'#23618c','BCL9L':'#a65735'}
 for ax,(mod,title) in zip(axs,[('PIAS_transcript_hypothesis','PIAS RNA module'),('Th1_cytotoxic_RNA_proxy','Th1/cytotoxic RNA proxy')]):
  for target,shift in [('BCL9',-.12),('BCL9L',.12)]:
   q=obs[obs.module.eq(mod)&obs.target_symbol.eq(target)]
   for i,c in enumerate(cultures):
    v=q[q.culture_condition.eq(c)].observed_module_mean.to_numpy();ax.scatter(np.full(len(v),i+shift),v,s=12,alpha=.7,color=colors[target]);ax.plot(i+shift,v.mean(),marker='_',ms=15,mew=2,color=colors[target])
   ax.plot([],[],marker='o',ls='',color=colors[target],label=target)
  ax.axhline(0,color='#555',lw=.8);ax.set_xticks(range(3),['Rest','8h','48h']);ax.set_title(title,fontsize=10);ax.set_ylabel('Mean RNA response',fontsize=10)
 fig.legend(*axs[0].get_legend_handles_labels(),loc='upper center',ncol=2,frameon=False,fontsize=10,bbox_to_anchor=(.53,1.03));fig.tight_layout(rect=[0,0,1,.88]);fp=W/'figures/bcl9_observed_modules.png';fig.savefig(fp);plt.close(fig)
 families=[('zero','Zero'),('source_training_mean','Training mean'),('source_same_target_mean','Target mean'),('concat_original_P1','Concat P1'),('fv_continued','Continued FV'),('fixed_gaussian','Fixed Gaussian'),('hierarchical','Hierarchy')];rows=[]
 for family,label in families:
  q=summary[summary.model.eq(family)].set_index('module');rows.append([label,f'{q.full_gene_MAE.iloc[0]:.6f}',f'{q.loc["PIAS_transcript_hypothesis","module_gene_MAE"]:.6f}',f'{q.loc["Th1_cytotoxic_RNA_proxy","module_gene_MAE"]:.6f}'])
 paper.append(page(heading('Appendix D  Literature-selected BCL9/BCL9L case'),figure(fp,'Figure S1. All four source donors for each target and culture. Points are observed aggregate RNA-module means in delta log2(1+CPM); bars denote arithmetic donor means. Colors distinguish the two single-target CRISPRi interventions, not a dual knockout. No donor or culture was selected for its direction.'),table(['Frozen predictor','Full-gene MAE','PIAS MAE','Effector-proxy MAE'],rows,[132,112,106,118],'Table S4. Six source fold-0 held-donor aggregates, 18,129 output features, all source seeds. The case was selected after benchmark inspection and cannot replace the complete held-donor or external comparisons.'),text('The three PIAS genes and all six RNA-proxy members (TBX21, IFNG, CXCR3, GZMA, GZMB, PRF1) are observed. The RNA-proxy members were fixed as a hypothesis-informed summary, not a validated functional score. All 24 source aggregates and individual genes are supplied in BCL9_all_observed_member_responses.csv. The complete per-seed case table is BCL9_all_case_model_seed_scores.csv.'),text('MAE reconstruction matches existing saved source evaluations to a maximum difference of 2.56e-8. No source model is refitted. The limited case has lower hierarchy full-gene MAE than zero response, but hierarchy does not improve the PIAS-member error; this subset cannot overturn the full benchmark. Neither STAT1/STAT4 RNA nor this proxy measures STAT phosphorylation, lineage frequency or tumor killing.')))
 paper.append(page(heading('Appendix E  Evidence required for pharmacological use'),table(['Evidence layer','Published motivation','What this manuscript can support'],[['Immune mechanism','Mouse Bcl9/Bcl9l deletion and hsBCL9 Z96; PIAS and phospho-STAT; Th1 function [11]','Human single-gene CRISPRi RNA illustration; assay/species transfer remains unvalidated'],['Tumor-cell pharmacology','ZD37-28R; MYC/SREBP1, lipid and glioma models [12]','Biological motivation and prospective endpoints; no compound response model or glioma prediction validation'],['Tissue / organ roadmap','Target-to-cell-to-function-to-organ development roadmap','A development plan; not a demonstrated multi-organ digital twin']],[105,177,186],'Table S5. Existing published wet-lab findings are attributed to their original studies. They are not relabeled as validation generated by FVcell.'),heading('E.1  Intervention and identifier integrity'),text('Record target, modality, dose, duration, species, subtype, donor, batch and comparator for every observation. hsBCL9 Z96 and ZD37-28R remain separate intervention identifiers; single knockdown is not dual deletion, and drug combination effects are not assigned to a single gene. SREBP1 is mapped to SREBF1 for transcript analysis. TCF4 is an ambiguous Wnt-literature label: official TCF4/E2-2 and TCF7L2 are distinct loci. Reagent sequences and gene identifiers must resolve that label before assigning a mechanistic edge; neither locus is scored here as a substitute for the other.'),heading('E.2  Matched measurements and a locked next test'),text('The minimum next package is a sample-to-file manifest, complete RNA counts if available, independent biological replicate identifiers, and paired functional readouts. PIAS transcripts, total and phospho-STAT1/4, T-bet/IFNg/granzyme measurements and measured killing should remain separate outputs. For glioma, use vehicle-matched ZD37-28R dose/time response, MYC/SREBF1 and lipid measurements, and appropriate rescue conditions. Per-sample wet-lab data underlying [11,12] were unavailable for this analysis; their published findings provide motivation rather than new model-validation labels.'),text('Before receiving outcomes, lock a compatible endpoint, split by biological sample, exclude overlapping source experiments, retain negative interventions and compare zero, source mean and simple target/linear baselines. Keep single-cell or technical replicates within their parent sample. A future fitted pathway or activity model must be evaluated as a new model, not retroactively claimed by this RNA-only case. Original mice, assays or figures do not create new independent validation merely by being added to the text.'),heading('E.3  Organ and exposure boundary'),text('Exposure, distribution, tissue composition and intercellular dynamics are required to move from cell response to organ-level efficacy or toxicity. The glioma article reports in vivo efficacy but explicitly leaves pharmacokinetics and brain/tumor exposure unresolved [12]. An FP competition IC50 is not a binding KD. Better combination tumor inhibition alone does not establish a formal interaction model, brain penetration, clinical safety or a calibrated organ simulator.')))
 return paper

def companion(cn,page,text,heading,table):
 cn.append(page(heading('本次生物学加强：BCL9/BCL9L 机制案例'),text('两篇原始论文补强了具体问题：一篇研究鼠 CD4 T 细胞的 Bcl9/Bcl9l 双敲或 hsBCL9 Z96 抑制与 PIAS–STAT–Th1 功能；另一篇研究 ZD37-28R 在胶质瘤中的 MYC/SREBP1 与脂质代谢。正文已加入动机、机制案例和跨尺度证据边界，新增两个附录；保留完整评测及全部外部负结果。'),text('现有源数据中有 BCL9 和 BCL9L：两靶点、四供者、三培养条件共 24 条聚合响应。按先固定的探索性案例方案，复用冻结 fold 0 三个种子，在六条留出供者响应上检查 PIAS 三基因和 Th1/细胞毒六基因 RNA 代理，未重新训练。所有基因、背景和种子均保留。'),table(['指标','实测','含义'],[['PIAS RNA 模块均值','+0.0410','不一致支持预期下降'],['效应 RNA 代理均值','-0.3683','不支持整体增强结论'],['层级模型 PIAS MAE','0.154919','零响应为 0.153639']],[178,104,186]),text('这里的人源单基因 CRISPRi 不等于鼠双敲，也不等于药物处理。这些结果不能反驳原论文在其对应实验中的结论，更不能声称模型复现了原论文。RNA 不能替代 STAT 磷酸化、Th1 比例和真实杀伤。机制名称 TCF4 还需核对基因 ID/试剂，避免与 TCF7L2 别名混淆；SREBP1 对应转录基因 SREBF1。'),heading('向课题组索取的首批文件'),text('先提供样本-文件-图号对应表、WT/双敲/药物组完整表达计数（如有）、Fig.7–8 逐样本 qPCR/蛋白/流式数值和使用许可。药物侧优先逐重复剂量/时间数据和机制/救援测量。可以先给 Excel、CSV、h5ad 或已有 RDS；FASTQ、BAM 和大影像不是第一批必需。'),text('详细需求见同目录生物学加强工作区的《课题组数据与源文件需求清单.md》，另有空白 sample_manifest_template.csv。用户正在向课题组确认数据可用性；没有把尚未提供的数据写成结果。'),heading('演示稿在本稿中的位置'),text('保留“靶点→细胞响应→功能实验→组织/器官”的应用路径。演示稿的细胞规模、任务覆盖、多器官和临床目标不转写为本文完成的能力。现有结果仍不足以补上顶会方法创新及有效性证据的缺口。三个输入原文件保持不变。')))
 return cn

def manifest_update(manifest):
 manifest.update(references=12,appendices=5,biology_strengthening='literature-grounded BCL9/BCL9L illustration plus explicit prospective endpoint plan; no new wet-lab or organ validation')
 for n in ['case_completion.json','protocol_case_study.json','case_model_summary.csv','source_files_before.json']:
  p=R/n;manifest['sources'][p.relative_to(B).as_posix()]=hashlib.sha256(p.read_bytes()).hexdigest()
 return manifest
